import os
import re
import glob
from PIL import Image, ImageOps
import pytesseract
import openpyxl
from datetime import datetime

# Configuration
IMG_DIR = '/app/workspace/dataset/img'
OUTPUT_FILE = '/app/workspace/stat_ocr.xlsx'

def get_files():
    files = glob.glob(os.path.join(IMG_DIR, '*.jpg'))
    return sorted(files, key=lambda x: os.path.basename(x))

def preprocess_image(path):
    try:
        img = Image.open(path)
        # Basic preprocessing for better OCR
        # Convert to grayscale
        img = img.convert('L')
        # Autocontrast to improve text clarity
        img = ImageOps.autocontrast(img)
        return img
    except Exception as e:
        print(f"Error preprocessing {path}: {e}")
        return None

def extract_text(path):
    img = preprocess_image(path)
    if img is None:
        return ""
    try:
        # Use psm 6 (Assume a single uniform block of text) - generally better for receipts
        text = pytesseract.image_to_string(img, config='--psm 6')
        return text
    except Exception as e:
        print(f"Error OCR {path}: {e}")
        return ""

def parse_date(text):
    # Regex patterns for date
    patterns = [
        # YYYY-MM-DD, YYYY/MM/DD
        (r'\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b', '%Y-%m-%d'),
        # DD/MM/YYYY, DD-MM-YYYY
        (r'\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b', '%d-%m-%Y'),
        # DD/MM/YY, DD-MM-YY (2-digit year)
        (r'\b(\d{1,2})[-/](\d{1,2})[-/](\d{2})\b', '%d-%m-%y'),
        # DD.MM.YYYY
        (r'\b(\d{1,2})\.(\d{1,2})\.(\d{4})\b', '%d.%m.%Y'),
        # DD MMM YYYY (e.g. 12 JAN 2022)
        (r'\b(\d{1,2})[\s-](\w{3})[\s-](\d{4})\b', '%d-%b-%Y'),
         # DD MMM YY (e.g. 12 JAN 22)
        (r'\b(\d{1,2})[\s-](\w{3})[\s-](\d{2})\b', '%d-%b-%y'),
    ]

    def validate_date(d):
        try:
            if 2000 <= d.year <= 2030:
                return True
        except:
            pass
        return False

    lines = text.split('\n')
    for line in lines:
        if not line.strip(): continue

        # Search for patterns
        for pat, fmt in patterns:
            try:
                matches = re.finditer(pat, line, re.IGNORECASE)
                for match in matches:
                    groups = match.groups()
                    d_str = ""
                    current_fmt = fmt

                    if fmt == '%Y-%m-%d': 
                        d_str = f"{groups[0]}-{groups[1]}-{groups[2]}"
                    elif fmt in ['%d-%m-%Y', '%d-%m-%y']:
                        d_str = f"{groups[0]}-{groups[1]}-{groups[2]}"
                    elif fmt == '%d.%m.%Y':
                        d_str = f"{groups[0]}.{groups[1]}.{groups[2]}"
                    elif fmt in ['%d-%b-%Y', '%d-%b-%y']:
                        month = groups[1].capitalize()
                        d_str = f"{groups[0]}-{month}-{groups[2]}"

                    try:
                        d = datetime.strptime(d_str, current_fmt)
                        if validate_date(d):
                            return d.strftime("%Y-%m-%d")
                    except ValueError:
                        continue
            except Exception:
                continue

    return None

def parse_total(text):
    lines = [line.strip() for line in text.split('\n') if line.strip()]

    keywords_priority = [
        ['grand total'],
        ['total rm', 'total: rm'],
        ['total amount'],
        ['total', 'amount', 'total due', 'amount due', 'balance due', 'nett total', 'net total']
    ]

    # Prompt exclusion list
    base_exclusion_keywords = ['subtotal', 'sub total', 'tax', 'gst', 'sst', 'discount', 'change', 'cash tendered']
    # Added 'cash' to avoid picking up payment lines as total
    extra_exclusion_keywords = ['cash'] 

    exclusion_keywords = base_exclusion_keywords + extra_exclusion_keywords

    # Regex to capture amount with potential spaces: 12 . 34 or 12 34
    # We allow space as separator, but it must be 2 digits at end.
    amount_re = re.compile(r'(\d{1,3}(?:[,]\d{3})*)\s?[\. ]\s?(\d{2})\b')

    def is_excluded(line_text):
        l_lower = line_text.lower()
        for exc in exclusion_keywords:
            if exc in l_lower:
                # Special handling for GST: if 'incl' is present, do NOT exclude based on GST
                if exc == 'gst' and ('incl' in l_lower or 'inc' in l_lower):
                    continue
                return True
        return False

    for keywords in keywords_priority:
        for i, line in enumerate(lines):
            line_lower = line.lower()

            if is_excluded(line):
                continue

            found_keyword = False
            for kw in keywords:
                if kw in line_lower:
                    found_keyword = True
                    break

            if found_keyword:
                def extract_from_line(l):
                    nums = amount_re.findall(l)
                    if nums:
                        val = nums[-1]
                        return val[0].replace(',', '') + '.' + val[1]
                    return None

                val = extract_from_line(line)
                if val: return val

                # Fallback: check next line
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    if not is_excluded(next_line):
                        val_next = extract_from_line(next_line)
                        if val_next: return val_next

    return None

def main():
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    files = get_files()
    for f in files:
        fname = os.path.basename(f)
        # print(f"Processing {fname}...", end=' ', flush=True)
        try:
            text = extract_text(f)

            date_str = parse_date(text)
            total_str = parse_total(text)

            # Debug output to verify
            # print(f"-> Date: {date_str}, Total: {total_str}")

            ws.append([fname, date_str, total_str])
        except Exception as e:
            print(f"\nError processing {fname}: {e}")
            ws.append([fname, None, None])

    wb.save(OUTPUT_FILE)
    print(f"Extraction complete. Saved to {OUTPUT_FILE}")

if __name__ == '__main__':
    main()
